// Example feeder: fetch the top Hacker News stories (zero credentials).
// Publishing is delegated to the dependent 'HN notify' sub-workflow, which
// owns the notifications.json contract (dedupe + atomic write).
const ids = await this.helpers.httpRequest({ url: 'https://hacker-news.firebaseio.com/v0/topstories.json', json: true });
const stories = [];
for (const id of ids.slice(0, 10)) {
  const it = await this.helpers.httpRequest({ url: `https://hacker-news.firebaseio.com/v0/item/${id}.json`, json: true });
  if (!it || !it.title) continue;
  stories.push({
    ts: new Date((it.time || 0) * 1000).toISOString(),
    title: it.title,
    message: `HN · ${it.score || 0} points`,
    status: 'info',
    link: it.url || `https://news.ycombinator.com/item?id=${id}`,
  });
}
return [{ json: { stories } }];
